"use strict";

// The package's whole callable API is chosen AT RUNTIME, by an early
// RETURN out of module evaluation -- the shape RWF-015 is about. Unlike
// RWF-014's `if`/`else`, the LAST `module.exports` write here is a
// syntactically UNCONDITIONAL top-level statement, so RWF-014's authority
// test accepts it. It is still not the module's value on every run.
const danger = require("./danger");

// The branch that reaches the vulnerable sink. Nothing in this file calls
// it: the ONLY way it ever runs is by being the module's exported value.
function dangerousOp(input) {
  return danger.explode(input);
}

// The branch that does not.
function safeOp(input) {
  return "safe:" + input;
}

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // Node wraps every CommonJS module in a function, so this `return` ends
  // module evaluation. The statement below NEVER runs on this path.
  return;
}

module.exports = safeOp;
